declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_access();$manage=perpus_can_manage();$id=(int)($_GET['id']??$_POST['id']??0);$error='';$flash=perpus_flash();
if($_SERVER['REQUEST_METHOD']==='POST'&&$manage){require_valid_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){$st=$pdo->prepare('SELECT COUNT(*) FROM perpustakaan_detail_peminjaman WHERE buku_id=?');$st->execute([$id]);$hist=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(*) FROM perpustakaan_eksemplar WHERE buku_id=?');$st->execute([$id]);$ex=(int)$st->fetchColumn();if($hist||$ex)$error='Buku sudah memiliki eksemplar/riwayat peminjaman dan tidak dapat dihapus. Nonaktifkan saja.';else{$pdo->prepare('DELETE FROM perpustakaan_buku WHERE id=?')->execute([$id]);perpus_audit($pdo,'DELETE',$id,'Menghapus buku perpustakaan');perpus_flash('Buku dihapus.');redirect('perpustakaan/buku.php');}}
 elseif($action==='toggle'){$pdo->prepare("UPDATE perpustakaan_buku SET status=IF(status='tersedia','nonaktif','tersedia') WHERE id=?")->execute([$id]);perpus_audit($pdo,'UPDATE',$id,'Mengubah status buku');perpus_flash('Status buku diperbarui.');redirect('perpustakaan/buku.php');}
 else{$d=[];foreach(['kode_buku','isbn','judul','penulis','penerbit','lokasi','keterangan'] as $k)$d[$k]=trim((string)($_POST[$k]??''));$tahun=(int)($_POST['tahun_terbit']??0);$kategori=(int)($_POST['kategori_id']??0);$jumlah=(int)($_POST['jumlah_eksemplar']??0);$kondisi=(string)($_POST['kondisi']??'baik');$status=(string)($_POST['status']??'tersedia');if($d['kode_buku']===''||$d['judul']===''||$jumlah<0)$error='Kode, judul, dan jumlah eksemplar wajib valid.';elseif(!in_array($kondisi,['baik','rusak_ringan','rusak_berat'],true)||!in_array($status,['tersedia','nonaktif'],true))$error='Nilai kondisi/status tidak valid.';else{try{$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE perpustakaan_buku SET kode_buku=?,isbn=?,judul=?,penulis=?,penerbit=?,tahun_terbit=?,kategori_id=?,lokasi=?,kondisi=?,status=?,keterangan=? WHERE id=?')->execute([$d['kode_buku'],$d['isbn']?:null,$d['judul'],$d['penulis']?:null,$d['penerbit']?:null,$tahun?:null,$kategori?:null,$d['lokasi']?:null,$kondisi,$status,$d['keterangan']?:null,$id]);$new=$id;perpus_audit($pdo,'UPDATE',$id,'Mengubah master buku perpustakaan');perpus_flash('Data buku diperbarui.');}else{$st=$pdo->prepare('INSERT INTO perpustakaan_buku(kode_buku,isbn,judul,penulis,penerbit,tahun_terbit,kategori_id,stok,lokasi,kondisi,status,keterangan) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$d['kode_buku'],$d['isbn']?:null,$d['judul'],$d['penulis']?:null,$d['penerbit']?:null,$tahun?:null,$kategori?:null,$jumlah,$d['lokasi']?:null,$kondisi,$status,$d['keterangan']?:null]);$new=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO perpustakaan_eksemplar(buku_id,kode_eksemplar,kondisi,status,lokasi) VALUES(?,?,?,?,?)');for($n=1;$n<=$jumlah;$n++)$ins->execute([$new,$d['kode_buku'].'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT),$kondisi,'tersedia',$d['lokasi']?:null]);perpus_audit($pdo,'CREATE',$new,'Menambah master buku dan '.$jumlah.' eksemplar');perpus_flash('Buku dan eksemplar berhasil ditambahkan.');}perpus_sync_stock($pdo,$new);$pdo->commit();redirect('perpustakaan/buku.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Kode buku sudah digunakan atau data tidak valid.':$e->getMessage();}}}}
$q=trim((string)($_GET['q']??''));$kat=(int)($_GET['kategori_id']??0);$where=[];$params=[];if($q!==''){$where[]='(b.kode_buku LIKE ? OR b.isbn LIKE ? OR b.judul LIKE ? OR b.penulis LIKE ?)';$like="%$q%";$params=[$like,$like,$like,$like];}if($kat>0){$where[]='b.kategori_id=?';$params[]=$kat;}$cats=$pdo->query('SELECT id,nama FROM perpustakaan_kategori WHERE aktif=1 ORDER BY nama')->fetchAll();$sql="SELECT b.*,k.nama kategori,COUNT(e.id) total_eksemplar,SUM(e.status='tersedia') tersedia_eksemplar FROM perpustakaan_buku b LEFT JOIN perpustakaan_kategori k ON k.id=b.kategori_id LEFT JOIN perpustakaan_eksemplar e ON e.buku_id=b.id".($where?' WHERE '.implode(' AND ',$where):'').' GROUP BY b.id ORDER BY b.judul';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$current=$id?null:['kode_buku'=>'','isbn'=>'','judul'=>'','penulis'=>'','penerbit'=>'','tahun_terbit'=>'','kategori_id'=>0,'stok'=>0,'lokasi'=>'','kondisi'=>'baik','status'=>'tersedia','keterangan'=>''];if($id){$st=$pdo->prepare('SELECT * FROM perpustakaan_buku WHERE id=?');$st->execute([$id]);$current=$st->fetch();if(!$current)exit('Buku tidak ditemukan.');}
$page_title='Buku Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main perpus-page"><header class="topbar"><div class="topbar-title">Data Buku</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-book-fill"></i> Data Buku</h1><p>Master judul buku dan eksemplar fisik. Setiap eksemplar memiliki QR unik.</p></div><div class="page-header-actions"><a class="btn btn-primary" href="<?=BASE_URL?>perpustakaan/import_buku.php"><i class="bi bi-file-earmark-spreadsheet"></i> Import XLSX</a><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div></div><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><form method="get" class="form-grid"><div class="form-group"><label>Pencarian</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Kode, ISBN, judul, penulis"></div><div class="form-group"><label>Kategori</label><select class="form-control" name="kategori_id"><option value="0">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$kat===(int)$c['id']?'selected':''?>><?=e($c['nama'])?></option><?php endforeach;?></select></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-search"></i> Cari</button></div></form></div><?php if($manage):?><div class="form-card"><h5><?= $id?'Edit':'Tambah' ?> Buku</h5><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="form-group"><label>Kode Buku *</label><input class="form-control" name="kode_buku" required value="<?=e($current['kode_buku'])?>" <?=$id?'readonly':''?>></div><div class="form-group"><label>ISBN</label><input class="form-control" name="isbn" value="<?=e($current['isbn']??'')?>"></div><div class="form-group form-group-full"><label>Judul *</label><input class="form-control" name="judul" required value="<?=e($current['judul'])?>"></div><div class="form-group"><label>Penulis</label><input class="form-control" name="penulis" value="<?=e($current['penulis']??'')?>"></div><div class="form-group"><label>Penerbit</label><input class="form-control" name="penerbit" value="<?=e($current['penerbit']??'')?>"></div><div class="form-group"><label>Tahun Terbit</label><input class="form-control" type="number" min="1900" max="2100" name="tahun_terbit" value="<?=e($current['tahun_terbit']??'')?>"></div><div class="form-group"><label>Kategori</label><select class="form-control" name="kategori_id"><option value="0">- Tidak ada -</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=((int)$current['kategori_id']===(int)$c['id'])?'selected':''?>><?=e($c['nama'])?></option><?php endforeach;?></select></div><div class="form-group"><label><?= $id?'Jumlah Eksemplar (dikelola di Eksemplar)':'Jumlah Eksemplar *' ?></label><input class="form-control" type="number" min="0" name="jumlah_eksemplar" value="<?=e($id?'0':$current['stok'])?>" <?=$id?'readonly':''?>><div class="form-text"><?= $id?'Untuk menambah eksemplar gunakan menu Kelola Eksemplar.':'' ?></div></div><div class="form-group"><label>Lokasi</label><input class="form-control" name="lokasi" value="<?=e($current['lokasi']??'')?>"></div><div class="form-group"><label>Kondisi awal</label><select class="form-control" name="kondisi"><?php foreach(['baik','rusak_ringan','rusak_berat'] as $v):?><option value="<?=$v?>" <?=$current['kondisi']===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="tersedia" <?=$current['status']==='tersedia'?'selected':''?>>Tersedia</option><option value="nonaktif" <?=$current['status']==='nonaktif'?'selected':''?>>Nonaktif</option></select></div><div class="form-group form-group-full"><label>Keterangan</label><textarea class="form-control" name="keterangan" rows="2"><?=e($current['keterangan']??'')?></textarea></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button><?php if($id):?><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/buku.php">Batal</a><?php endif;?></div></form></div><?php endif;?><div class="form-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Judul</th><th>Kategori</th><th>Eksemplar</th><th>Status</th><?php if($manage):?><th>Aksi</th><?php endif;?></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty-state">Belum ada buku.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['kode_buku'])?></td><td><strong><?=e($r['judul'])?></strong><div class="text-muted small"><?=e($r['penulis']??'-')?></div></td><td><?=e($r['kategori']??'-')?></td><td><strong><?=number_format((int)($r['tersedia_eksemplar']??0))?></strong> / <?=number_format((int)($r['total_eksemplar']??0))?> tersedia</td><td><?= $r['status']==='tersedia'?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>' ?></td><?php if($manage):?><td style="white-space:nowrap"><a class="btn btn-sm btn-primary btn-icon-sm" href="?id=<?=$r['id']?>" title="Edit master" aria-label="Edit master"><i class="bi bi-pencil-square"></i></a><a class="btn btn-sm btn-info btn-icon-sm" href="<?=BASE_URL?>perpustakaan/eksemplar.php?buku_id=<?=$r['id']?>" title="Kelola eksemplar" aria-label="Kelola eksemplar"><i class="bi bi-upc-scan"></i></a><a class="btn btn-sm btn-secondary btn-icon-sm" href="<?=BASE_URL?>perpustakaan/buku_qr.php?buku_id=<?=$r['id']?>" title="Cetak semua QR eksemplar" aria-label="Cetak semua QR eksemplar"><i class="bi bi-qr-code"></i></a><form method="post" class="d-inline" onsubmit="return confirm('Ubah status buku?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-sm btn-secondary" title="Aktif/nonaktif" aria-label="Aktif/nonaktif"><i class="bi bi-toggle-on"></i></button></form><form method="post" class="d-inline" onsubmit="return confirm('Hapus buku ini?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-danger" title="Hapus" aria-label="Hapus"><i class="bi bi-trash"></i></button></form></td><?php endif;?></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';
